class ScratchHintTest {

    private SQLStatement parse(final String sql) {
        SQLParserEngine parserEngine = new SQLParserEngine("SQLServer", new CacheOption(128, 1024L));
        ParseASTNode ast = parserEngine.parse(sql, false);
        return new SQLStatementVisitorEngine("SQLServer").visit(ast);
    }

    @Test
    void assertWithTableHint() {
        String sql = "INSERT INTO t1 WITH (TABLOCK) SELECT * FROM t2";
        InsertStatement stmt = (InsertStatement) parse(sql);
        System.out.println(">>> withTableHint present = " + InsertStatementHandler.getWithTableHintSegment(stmt).isPresent());
        InsertStatementHandler.getWithTableHintSegment(stmt).ifPresent(s -> {
            System.out.println(">>> hint start=" + s.getStartIndex() + " stop=" + s.getStopIndex());
            s.getTableHintLimitedSegments().forEach(h -> System.out.println(">>> limited value=" + h.getValue() + " [" + h.getStartIndex() + "," + h.getStopIndex() + "]"));
        });
    }

    @Test
    void assertExecNamedParams() {
        String sql = "INSERT INTO t1 EXEC my_proc @p1 = 1, @p2 = 'x'";
        parse(sql);
        System.out.println(">>> exec named params parsed OK");
    }

    @Test
    void assertArithmeticCast() {
        String sql = "SELECT CAST(SERVERPROPERTY('ProductVersion') AS INT) * 2 + 1 AS v";
        parse(sql);
        System.out.println(">>> arithmetic cast parsed OK");
    }

    @Test
    void assertComplexSelect() {
        String sql = "SELECT a.id, COUNT(*) AS c FROM t1 a JOIN t2 b ON a.id = b.id "
                + "WHERE a.name LIKE '%x%' AND b.code LIKE 'A%' GROUP BY a.id HAVING COUNT(*) > 1 ORDER BY a.id";
        parse(sql);
        System.out.println(">>> complex select parsed OK");
    }
}
